		public frmInputDetail(V_HIS_SERE_SERV_5 sereServ, HIS_EYE_SURGRY_DESC eyeSurgDesc, List<HIS_STENT_CONCLUDE> StenConclude, Action<HIS_EYE_SURGRY_DESC> getEyeSurgryDescLast, SkinSurgeryDesADO skinSurgeryDes, Action<SkinSurgeryDesADO> actionSkinSurgeryDes, V_HIS_SERE_SERV_PTTT sereServPTTT, Action<V_HIS_SERE_SERV_PTTT> actionSereServPTTT, Action<List<HIS_STENT_CONCLUDE>> ActionStentConclude)
		{
			InitializeComponent();
			try
			{
				this.sereServ = sereServ;
				this.StenConclude = StenConclude;
				this.eyeSurgDesc = eyeSurgDesc;
				GetEyeSurgryDescLast = getEyeSurgryDescLast;
				SkinSurgeryDes = skinSurgeryDes;
				ActionSkinSurgeryDes = actionSkinSurgeryDes;
				SereServPTTT = sereServPTTT;
				ActionSereServPTTT = actionSereServPTTT;
				this.ActionStentConclude = ActionStentConclude;
				SetIcon();
			}
			catch (Exception ex)
			{
				LogSystem.Error(ex);
			}
		}

		private void SetIcon()
		{
			try
			{
				base.Icon = Icon.ExtractAssociatedIcon(Path.Combine(ApplicationStoreLocation.ApplicationDirectory, ConfigurationSettings.AppSettings["Inventec.Desktop.Icon"]));
			}
			catch (Exception ex)
			{
				LogSystem.Error(ex);
			}
		}

		private void frmInputDetail_Load(object sender, EventArgs e)
		{
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			//IL_002f: Expected O, but got Unknown
			try
			{
				SetCaptionByLanguageKey();
				xtraTabControl1.ShowTabHeader = DefaultBoolean.False;
				if (eyeSurgDesc == null)
				{
					eyeSurgDesc = new HIS_EYE_SURGRY_DESC();
				}
				LOAI_PT_MAT = eyeSurgDesc.LOAI_PT_MAT;
				long lOAI_PT_MAT = LOAI_PT_MAT;
				long num = lOAI_PT_MAT;
				long num2 = num - 1;
				if ((ulong)num2 > 6uL)
				{
					goto IL_0120;
				}
				switch (num2)
				{
				case 0L:
					break;
				case 1L:
					goto IL_0099;
				case 2L:
					goto IL_00b2;
				case 3L:
					goto IL_00c8;
				case 4L:
					goto IL_00de;
				case 5L:
					goto IL_00f4;
				case 6L:
					goto IL_010a;
				default:
					goto IL_0120;
				}
				raPTGlocom.Checked = true;
				LoadPTGlocom();
				goto IL_0136;
				IL_010a:
				raTTMongMat.Checked = true;
				LoadTTMongMat();
				goto IL_0136;
				IL_00f4:
				raTTLaser.Checked = true;
				LoadTTLaser();
				goto IL_0136;
				IL_0120:
				raPTMong.Checked = true;
				LoadTTMong();
				goto IL_0136;
				IL_0136:
				LoadTTSkin();
				LoadDMV();
				LoadSereServPTTT_Other();
				isFirstLoad = false;
				return;
				IL_0099:
				raPTMong.Checked = true;
				LoadTTMong();
				goto IL_0136;
				IL_00b2:
				raPTDucThuyTInhThe.Checked = true;
				LoadPTDucThuyTinhThe();
				goto IL_0136;
				IL_00c8:
				raPTTaiTaoLeQuan.Checked = true;
				LoadPTTaiTaoLeQuan();
				goto IL_0136;
				IL_00de:
				raPTSupMi.Checked = true;
				LoadPTSupMi();
				goto IL_0136;
			}
			catch (Exception ex)
			{
				LogSystem.Error(ex);
			}
		}

		private void LoadDMV()
		{
			try
			{
				lstDataDmv = new List<DmvADO>();
				lstDataDmv.Add(new DmvADO
				{
					Action = 1
				});
				if (SereServPTTT != null)
				{
					txtPci.Text = SereServPTTT.PCI;
					txtStenting.Text = SereServPTTT.STENTING;
					txtLocation.Text = SereServPTTT.LOCATION_INTERVENTION;
					txtReason.Text = SereServPTTT.REASON_INTERVENTION;
					txtIntroducer.Text = SereServPTTT.INTRODUCER;
					txtGuidingCatheter.Text = SereServPTTT.GUIDING_CATHETER;
					txtGuiteWire.Text = SereServPTTT.GUITE_WIRE;
					txtBallon.Text = SereServPTTT.BALLON;
					txtStent.Text = SereServPTTT.STENT;
					txtContrastAgent.Text = SereServPTTT.CONTRAST_AGENT;
					txtInstrumentsOther.Text = SereServPTTT.INSTRUMENTS_OTHER;
					memStentNote.Text = SereServPTTT.STENT_NOTE;
					if (StenConclude != null && StenConclude.Count > 0)
					{
						lstDataDmv = new List<DmvADO>();
						StenConclude.ForEach(delegate(HIS_STENT_CONCLUDE o)
						{
							lstDataDmv.Add(new DmvADO(o)
							{
								Action = 2
							});
						});
						lstDataDmv.LastOrDefault().Action = 1;
					}
				}
				gridControl1.DataSource = null;
				gridControl1.DataSource = lstDataDmv;
			}
			catch (Exception ex)
			{
				LogSystem.Error(ex);
			}
		}

		private void LoadSereServPTTT_Other()
		{
			try
			{
				if (SereServPTTT != null)
				{
					txtDrainage.Text = SereServPTTT.DRAINAGE;
					txtWick.Text = SereServPTTT.WICK;
					if (SereServPTTT.DRAW_DATE.HasValue)
					{
						dtDrawDate.DateTime = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(SereServPTTT.DRAW_DATE.GetValueOrDefault()).GetValueOrDefault();
					}
					if (SereServPTTT.CUT_SEWING_DATE.HasValue)
					{
						dtSewingDate.DateTime = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(SereServPTTT.CUT_SEWING_DATE.GetValueOrDefault()).GetValueOrDefault();
					}
					txtOther.Text = SereServPTTT.OTHER;
				}
			}
			catch (Exception ex)
			{
				LogSystem.Error(ex);
			}
		}

		private void LoadTTSkin()
		{
			try
			{
				if (SkinSurgeryDes == null)
				{
					return;
				}
				xtraTabAddInfo.SelectedTabPage = xtraTabSkin;
				if (SkinSurgeryDes != null && SkinSurgeryDes.SURGERY_POSITION_ID.HasValue)
				{
					if (SkinSurgeryDes.SURGERY_POSITION_ID.Value == 1)
					{
						chkPostureUp.Checked = true;
					}
					else if (SkinSurgeryDes.SURGERY_POSITION_ID.Value == 2)
					{
						chkPostureSide.Checked = true;
					}
					else if (SkinSurgeryDes.SURGERY_POSITION_ID.Value == 3)
					{
						chkPostureTummy.Checked = true;
					}
				}
				if (SkinSurgeryDes == null)
				{
					return;
				}
				txtSkinDamage.Text = ((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE;
				txtSkinDamagePosition.Text = ((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_POSITION;
				spSkinDamageAmount.EditValue = ((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_AMOUNT;
				if (((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CUTTING_TYPE.HasValue)
				{
					if (((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CUTTING_TYPE.Value == 1)
					{
						chkDamageTypeAll.Checked = true;
					}
					else if (((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CUTTING_TYPE.Value == 2)
					{
						chkDamageTypePart.Checked = true;
					}
				}
				if (((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_SHAPING_TYPE.HasValue)
				{
					if (((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_SHAPING_TYPE.Value == 1)
					{
						chkShapingSkin.Checked = true;
					}
					else if (((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_SHAPING_TYPE.Value == 2)
					{
						chkShapingSkinOther.Checked = true;
					}
				}
				if (((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CLOSING_TYPE.HasValue)
				{
					if (((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CLOSING_TYPE.Value == 1)
					{
						chkCloseSkin.Checked = true;
					}
					else if (((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CLOSING_TYPE.Value == 2)
					{
						chkDiscloseSkin.Checked = true;
					}
				}
				txtTreatSkinOther.Text = ((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_OTHER;
			}
			catch (Exception ex)
			{
				LogSystem.Error(ex);
			}
		}

		private void LoadPTTaiTaoLeQuan()
		{
			try
			{
				if (!isReset)
				{
					DefaultChosen();
					TextDefault();
					if (eyeSurgDesc.CHAN_DOAN_DUT_LE_QUAN == 1)
					{
						checkEdit205.Checked = true;
					}
					else if (eyeSurgDesc.CHAN_DOAN_DUT_LE_QUAN == 2)
					{
						checkEdit201.Checked = true;
					}
					else if (eyeSurgDesc.CHAN_DOAN_DUT_LE_QUAN == 3)
					{
						checkEdit204.Checked = true;
					}
					spinEdit51.EditValue = eyeSurgDesc.DUT_LE_QUAN_GIO_THU;
					if (eyeSurgDesc.PP_PHAU_THUAT_LE_QUAN == 1)
					{
						checkEdit200.Checked = true;
					}
					else if (eyeSurgDesc.PP_PHAU_THUAT_LE_QUAN == 2)
					{
						checkEdit197.Checked = true;
					}
					spinEdit52.EditValue = eyeSurgDesc.PHAU_THUAT_LAN_THU;
					if (eyeSurgDesc.PP_VO_CAM == 1)
					{
						checkEdit194.Checked = true;
					}
					else if (eyeSurgDesc.PP_VO_CAM == 2)
					{
						checkEdit193.Checked = true;
					}
					if (!eyeSurgDesc.PP_VO_CAM_DUOI_HOC.HasValue || eyeSurgDesc.PP_VO_CAM_DUOI_HOC == 1)
					{
						checkEdit192.Checked = true;
					}
					if (!eyeSurgDesc.PP_VO_CAM_MUI.HasValue || eyeSurgDesc.PP_VO_CAM_MUI == 1)
					{
						checkEdit191.Checked = true;
					}
					if (!eyeSurgDesc.PP_VO_CAM_VUNG_TUI_LE.HasValue || eyeSurgDesc.PP_VO_CAM_VUNG_TUI_LE == 1)
					{
