		private void GetDataDmv()
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			//IL_001a: Expected O, but got Unknown
			//IL_01e5: Unknown result type (might be due to invalid IL or missing references)
			//IL_01eb: Expected O, but got Unknown
			try
			{
				if (SereServPTTT == null)
				{
					SereServPTTT = new V_HIS_SERE_SERV_PTTT();
				}
				StenConclude = new List<HIS_STENT_CONCLUDE>();
				SereServPTTT.PCI = txtPci.Text.Trim();
				SereServPTTT.STENTING = txtStenting.Text.Trim();
				SereServPTTT.LOCATION_INTERVENTION = txtLocation.Text.Trim();
				SereServPTTT.REASON_INTERVENTION = txtReason.Text.Trim();
				SereServPTTT.INTRODUCER = txtIntroducer.Text.Trim();
				SereServPTTT.GUIDING_CATHETER = txtGuidingCatheter.Text.Trim();
				SereServPTTT.GUITE_WIRE = txtGuiteWire.Text.Trim();
				SereServPTTT.BALLON = txtBallon.Text.Trim();
				SereServPTTT.STENT = txtStent.Text.Trim();
				SereServPTTT.CONTRAST_AGENT = txtContrastAgent.Text.Trim();
				SereServPTTT.INSTRUMENTS_OTHER = txtInstrumentsOther.Text.Trim();
				SereServPTTT.STENT_NOTE = memStentNote.Text.Trim();
				foreach (DmvADO item in lstDataDmv)
				{
					if (!string.IsNullOrEmpty(((HIS_STENT_CONCLUDE)item).SURGERY_NAME) || !string.IsNullOrEmpty(((HIS_STENT_CONCLUDE)item).DEVICE_NAME) || !string.IsNullOrEmpty(((HIS_STENT_CONCLUDE)item).BALLON_PRESSURE_TIME) || ((HIS_STENT_CONCLUDE)item).RESULT_BEFORE.HasValue || ((HIS_STENT_CONCLUDE)item).RESULT_AFTER.HasValue)
					{
						HIS_STENT_CONCLUDE val = new HIS_STENT_CONCLUDE();
						DataObjectMapper.Map<HIS_STENT_CONCLUDE>((object)val, (object)item);
						val.SERE_SERV_ID = sereServ.ID;
						StenConclude.Add(val);
					}
				}
			}
			catch (Exception ex)
			{
				LogSystem.Error(ex);
			}
		}

