		private void GetDataTTDalieu()
		{
			try
			{
				if (SkinSurgeryDes == null)
				{
					SkinSurgeryDes = new SkinSurgeryDesADO();
				}
				if (chkPostureUp.Checked)
				{
					SkinSurgeryDes.SURGERY_POSITION_ID = 1L;
				}
				else if (chkPostureSide.Checked)
				{
					SkinSurgeryDes.SURGERY_POSITION_ID = 2L;
				}
				else if (chkPostureTummy.Checked)
				{
					SkinSurgeryDes.SURGERY_POSITION_ID = 3L;
				}
				else
				{
					SkinSurgeryDes.SURGERY_POSITION_ID = null;
				}
				((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE = txtSkinDamage.Text;
				((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_POSITION = txtSkinDamagePosition.Text;
				if (spSkinDamageAmount.EditValue != null && spSkinDamageAmount.Value > 0m)
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_AMOUNT = (long)spSkinDamageAmount.Value;
				}
				else
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_AMOUNT = null;
				}
				if (chkDamageTypeAll.Checked)
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CUTTING_TYPE = 1L;
				}
				else if (chkDamageTypePart.Checked)
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CUTTING_TYPE = 2L;
				}
				else
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CUTTING_TYPE = null;
				}
				if (chkShapingSkin.Checked)
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_SHAPING_TYPE = 1L;
				}
				else if (chkShapingSkinOther.Checked)
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_SHAPING_TYPE = 2L;
				}
				else
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_SHAPING_TYPE = null;
				}
				if (chkCloseSkin.Checked)
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CLOSING_TYPE = 1L;
				}
				else if (chkDiscloseSkin.Checked)
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CLOSING_TYPE = 2L;
				}
				else
				{
					((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_CLOSING_TYPE = null;
				}
				((HIS_SKIN_SURGERY_DESC)SkinSurgeryDes).DAMAGE_TREAT_OTHER = txtTreatSkinOther.Text;
				SkinSurgeryDes.HasValue = true;
			}
			catch (Exception ex)
			{
				LogSystem.Error(ex);
			}
		}

