		private void gridView1_CustomRowCellEdit(object sender, CustomRowCellEditEventArgs e)
		{
			try
			{
				if (e.Column.FieldName == "Action")
				{
					int num = System.Convert.ToInt32(e.RowHandle);
					int num2 = Parse.ToInt32((gridView1.GetRowCellValue(e.RowHandle, "Action") ?? "").ToString());
					if (num2 == 1)
					{
						e.RepositoryItem = repPlus;
					}
					else
					{
						e.RepositoryItem = repMinus;
					}
				}
			}
			catch (Exception ex)
			{
				LogSystem.Warn(ex);
			}
		}

		private void btnReset_Click(object sender, EventArgs e)
		{
			try
			{
				isReset = true;
				List<LayoutControl> list = new List<LayoutControl> { lcPtDucTTT, lcGlocom, lcPtMong, lcPtSupMi, lcTaiTaoLeQuan, lcTTMongMat, lcTTTLaser, lcDaLieu, lcDieuTriCanThiepDMV, layoutControl_TabOther };
				foreach (LayoutControl item in list)
				{
					item.BeginUpdate();
					try
					{
						foreach (BaseLayoutItem item2 in item.Items)
						{
							LayoutControlItem layoutControlItem = item2 as LayoutControlItem;
							if (layoutControlItem != null && layoutControlItem.Control != null)
							{
								if (layoutControlItem.Control is BaseEdit && !(layoutControlItem.Control is CheckEdit))
								{
									BaseEdit baseEdit = layoutControlItem.Control as BaseEdit;
									baseEdit.EditValue = null;
									baseEdit.Text = null;
								}
								else if (layoutControlItem.Control is CheckEdit)
								{
									CheckEdit checkEdit = layoutControlItem.Control as CheckEdit;
									checkEdit.Checked = false;
								}
							}
						}
					}
					catch (Exception ex)
					{
						LogSystem.Warn(ex);
					}
					finally
					{
						item.EndUpdate();
					}
				}
			}
			catch (Exception ex2)
			{
				LogSystem.Warn(ex2);
			}
		}

